import { CommonModule } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { QIconComponent } from '@questrade/allspark-angular-components/icon';
import { QBadgeContext } from './types/badge-context.type';
import { QBadgePlacement } from './types/badge-placement.type';
import { QBadgePosition } from './types/badge-position.type';
import { QBadgeVariant } from './types/badge-variant.type';

@Component({
  selector: 'q-badge',
  templateUrl: './badge.component.html',
  styleUrls: ['./badge.component.scss'],
  imports: [CommonModule, QIconComponent],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QBadgeComponent {
  @Input() iconName = '';
  @Input() text = '';
  @Input() variant: QBadgeVariant = 'dot';
  @Input() position: QBadgePosition = 'above after';
  @Input() placement: QBadgePlacement = 'corner';
  @Input() context: QBadgeContext = 'danger';
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-badge-hidden') hide = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-badge';

  @HostBinding('class') get _hostClasses(): string {
    return [
      'q-badge',
      `q-badge-${this.context}`,
      `q-badge-${this.variant}`,
      `q-badge-${this.verticalPosition}`,
      `q-badge-${this.horizontalPosition}`,
      `q-badge-${this.placement}`,
    ]
      .filter((className) => className !== 'q-badge-')
      .join(' ');
  }

  get verticalPosition(): string {
    return this.position.replace(/ \S+/, '') ?? 'above';
  }

  get horizontalPosition(): string {
    return this.position.replace(/\S+ /, '') ?? 'after';
  }
}
